recipes.code:
{
  "inputs": [
    {
      "id": "numeratica-api-key",
      "type": "promptString",
      "description": "Numeratica API key (nmr_sk_...). Free self-serve key at https://docs.numeratica.com/get-key",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@numeratica/mcp@0.1.5"
      ],
      "env": {
        "NUMERATICA_API_KEY": "${input:numeratica-api-key}",
        "NUMERATICA_BASE_URL": "<numeratica-base-url>",
        "NUMERATICA_TIMEOUT_MS": "<numeratica-timeout-ms>"
      }
    }
  }
}
